# Master data model for the Beethoven catalog + KML generation.
# Every entry appears in BOTH catalog.html (as a card w/ anchor id) and the KML
# (as a Placemark whose description links back to that anchor).

ROOT = "https://tripperist.github.io/beethoven/"
CATALOG_URL = ROOT + "catalog.html"
INDEX_URL = ROOT + "index.html"

def maps_url(coords):
    # coords are stored KML-style as "lon,lat,alt" — Google Maps wants "lat,lon"
    lon, lat, *_ = coords.split(",")
    return f"https://www.google.com/maps?q={lat},{lon}"

# kind -> kml styleUrl
